def make_file_tools(ws) -> list[Tool]:
    """闭包绑定 ws 的 read/write/ls。不碰进程 cwd → 多 agent 不踩踏(原则 14)。"""
    ws = Path(ws)

    def _resolve(p):
        p = Path(p)
        return p if p.is_absolute() else ws / p

    def read(args):
